<div class="page-heading"><span class="eyebrow">AKTIVITASMU</span><h1>Riwayat pesanan</h1><p>Periksa status pesanan, metode pemenuhan, dan riwayat transaksi kamu.</p></div><?php if(!$orders): ?><div class="empty-state"><div class="empty-icon">▤</div><h3>Belum ada pesanan</h3><p>Produk surplus yang kamu pesan akan tampil di sini.</p><a href="?page=catalog" class="btn btn-primary">Jelajahi katalog</a></div><?php else: ?><div class="order-list"><?php foreach($orders as $o): ?><article class="panel order-card"><div class="order-card-head"><div><span class="eyebrow">ORDER #ORD-<?= (int)$o['order_id'] ?></span><h3><?= e($o['product_names'] ?: 'Pesanan') ?></h3><span class="muted small"><?= e(date('d M Y, H:i',strtotime($o['order_date']))) ?></span></div><span class="status status-<?= e($o['status']) ?>"><?= e(str_replace('_',' ',$o['status'])) ?></span></div><div class="order-card-detail"><span>Metode: <strong><?= e($o['fulfillment_method']) ?></strong></span><span>Bayar: <strong><?= e($o['payment_status']) ?></strong></span><span>Total: <strong><?= money($o['total_amount']) ?></strong></span><span>Fulfillment: <strong><?= e(str_replace('_',' ',$o['delivery_status']??'belum_diproses')) ?></strong></span></div><div class="order-card-actions"><?php if($o['status']==='menunggu_pembayaran'): ?><a class="btn btn-primary btn-small" href="?page=payment&id=<?= (int)$o['order_id'] ?>">Lanjut pembayaran</a><?php endif; ?><?php if(in_array($o['status'],['menunggu_pembayaran','dibayar'],true)): ?><form method="post" class="inline" data-confirm="Batalkan pesanan ini? Jika sudah dibayar, pengembalian dana akan disimulasikan."><?= csrf_field() ?><input type="hidden" name="action" value="cancel_order"><input type="hidden" name="order_id" value="<?= (int)$o['order_id'] ?>"><button class="btn btn-outline btn-small">Batalkan pesanan</button></form><?php endif; ?></div></article><?php endforeach; ?></div><?php endif; ?>
